WITH enriched AS (SELECT *, LAG(status_bits) OVER (PARTITION BY device_code ORDER BY humidity, id) AS prev_status_bits, LAG(humidity) OVER (PARTITION BY device_code ORDER BY humidity, id) AS prev_humidity, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY humidity, id) AS seq_no FROM device_readings WHERE status_bits <> 10) SELECT id, temp_c, humidity, pressure, status_bits, firmware, prev_humidity FROM enriched ORDER BY prev_humidity DESC NULLS LAST;
